const itemById = new Map();
const itemByNormalizedQuestion = new Map();

for (const item of MARKET_GAP_BATCH_1) {
  itemById.set(item.id, item);
  itemByNormalizedQuestion.set(normalizeText(item.question), item);
}

function normalizeText(text) {
  if (!text || typeof text !== 'string') return '';
  return text.toLowerCase()
    .replace(/[\s\p{P}]+/gu, ' ')
    .trim();
}

/**
 * Resolves a Market Gap question from Batch 1 (80,001 - 82,000)
 * @param {string|number} queryOrId - Numeric ID or question string
 * @returns {object|null} Matched item with verified statutory authority
 */
export function resolveMarketGapBatch1Item(queryOrId) {
  if (queryOrId === undefined || queryOrId === null) return null;

  // 1. Direct Numeric ID Lookup
  if (typeof queryOrId === 'number' || /^\d+$/.test(String(queryOrId).trim())) {
    const id = Number(queryOrId);
    if (id >= 80001 && id <= 82000) {
      return itemById.get(id) || null;
    }
    return null;
  }

  // 2. String ID pattern (e.g. "GMS-MKT-Q80001" or "80001")
  const idMatch = String(queryOrId).match(/\b(?:GMS-MKT-Q)?(8[0-1]\d{3}|82000)\b/i);
  if (idMatch) {
    const id = Number(idMatch[1]);
    const item = itemById.get(id);
    if (item) return item;
  }

  const cleanQ = normalizeText(queryOrId);
  if (!cleanQ || cleanQ.length < 20) return null;

  // 3. Exact Normalized Question Match
  const exact = itemByNormalizedQuestion.get(cleanQ);
  if (exact) return exact;

  // 4. Substring Match with Bounded Length
  if (cleanQ.length >= 35) {
    for (const item of MARKET_GAP_BATCH_1) {
      const norm = normalizeText(item.question);
      if (norm.includes(cleanQ) || cleanQ.includes(norm)) {
        return item;
      }
    }
  }

  // 5. High-Confidence Scenario & Country Token Match
  const scenarioMatches = [
    { pattern: /portal shows zero documents after successful upload/i, range: [80001, 80200] },
    { pattern: /biometrics completed but online status remains pending/i, range: [80201, 80400] },
    { pattern: /account locked after changing phone number/i, range: [80401, 80600] },
    { pattern: /duplicate profiles created under different emails/i, range: [80601, 80800] },
    { pattern: /government portal cannot accept non-Latin name characters/i, range: [80801, 81000] },
    { pattern: /upload deadline falls during a portal outage/i, range: [81001, 81200] },
    { pattern: /webform acknowledgment arrived but requested documents not/i, range: [81201, 81400] },
    { pattern: /application fee charged twice while only one submission/i, range: [81401, 81600] },
    { pattern: /address history contains an unexplained two-month gap/i, range: [81601, 81800] },
    { pattern: /former employer closed and cannot issue reference letter/i, range: [81801, 82000] }
  ];

  for (const s of scenarioMatches) {
    if (s.pattern.test(queryOrId)) {
      // Find item in this range matching country
      for (let id = s.range[0]; id <= s.range[1]; id++) {
        const candidate = itemById.get(id);
        if (candidate && cleanQ.includes(candidate.country.toLowerCase())) {
          return candidate;
        }
      }
      // Return first item of the scenario if country unspecified
      return itemById.get(s.range[0]) || null;
    }
  }

  return null;
}

/**
 * Searches questions in Batch 1 by query, country, or topic
 */
export function searchMarketGapBatch1(params = {}) {
  const safeParams = (params && typeof params === 'object') ? params : {};
  const { query, country, topic, limit = 20, offset = 0 } = safeParams;
  let results = MARKET_GAP_BATCH_1;

  if (country) {
    const cLower = country.toLowerCase().trim();
    results = results.filter(i => i.country.toLowerCase() === cLower);
  }

  if (topic) {
    const tLower = topic.toLowerCase().trim();
    results = results.filter(i => i.topic.toLowerCase() === tLower);
  }

  if (query && query.trim().length > 0) {
    const norm = normalizeText(query);
    results = results.filter(i => 
      normalizeText(i.question).includes(norm) ||
      i.citation.toLowerCase().includes(norm) ||
      i.statutoryRule.toLowerCase().includes(norm) ||
      i.verdict.toLowerCase().includes(norm) ||
      String(i.id).includes(norm)
    );
  }

  const total = results.length;
  const paginated = results.slice(offset, offset + limit);

  return {
    total,
    offset,
    limit,
    items: paginated
  };
}

/**
 * Returns statistics and coverage details for Batch 1
 */
export function getMarketGapBatch1Stats() {
  const byTier = {};
  const byTopic = {};
  const byScenario = {};
  const byCountry = {};

  for (const item of MARKET_GAP_BATCH_1) {
    byTier[item.tier] = (byTier[item.tier] || 0) + 1;
    byTopic[item.topic] = (byTopic[item.topic] || 0) + 1;
    byScenario[item.scenarioName] = (byScenario[item.scenarioName] || 0) + 1;
    byCountry[item.country] = (byCountry[item.country] || 0) + 1;
  }

  return {
    totalQuestions: MARKET_GAP_BATCH_1.length,
    range: '80001 - 82000',
    tiers: byTier,
    topics: byTopic,
    scenarios: byScenario,
    totalCountries: Object.keys(byCountry).length
  };
}
